CREATE DATABASE IF NOT EXISTS eventflow CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE eventflow;
CREATE TABLE IF NOT EXISTS users(id INT AUTO_INCREMENT PRIMARY KEY,first_name VARCHAR(100) NOT NULL,last_name VARCHAR(100) NOT NULL,email VARCHAR(190) NOT NULL UNIQUE,password_hash VARCHAR(255) NOT NULL,phone VARCHAR(30) NULL,role VARCHAR(30) NOT NULL DEFAULT 'user',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
INSERT IGNORE INTO users(first_name,last_name,email,password_hash,role) VALUES('Franck','Nganou','franck06.nganou02oumbe2004@gmail.com','$2y$10$7TFlxYzz0JpeA69946TPaeeGOnqIbRLHBskRFyj.CFIFhoKCMP/lO','admin');
CREATE TABLE IF NOT EXISTS events(id BIGINT AUTO_INCREMENT PRIMARY KEY,organizer_id INT NOT NULL,title VARCHAR(200) NOT NULL,event_date DATETIME NOT NULL,end_date DATETIME NULL,location VARCHAR(255) NOT NULL,price DECIMAL(10,2) NOT NULL,image TEXT,capacity INT NOT NULL,available_tickets INT NOT NULL,category VARCHAR(80) NOT NULL,description TEXT NOT NULL,created_by VARCHAR(190) NOT NULL,status ENUM('draft','published','ongoing','completed','cancelled') NOT NULL DEFAULT 'draft',visibility ENUM('public','private') NOT NULL DEFAULT 'public',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(organizer_id) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS event_ticket_types(id VARCHAR(80) NOT NULL,event_id BIGINT NOT NULL,name VARCHAR(100) NOT NULL,price DECIMAL(10,2) NOT NULL,quantity INT NOT NULL,available_quantity INT NOT NULL,max_per_order INT NOT NULL DEFAULT 10,sales_start DATETIME NULL,sales_end DATETIME NULL,description VARCHAR(255) NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(event_id,id),FOREIGN KEY(event_id) REFERENCES events(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS organizer_requests(id BIGINT AUTO_INCREMENT PRIMARY KEY,user_id INT NOT NULL UNIQUE,organization_name VARCHAR(190) NOT NULL,phone VARCHAR(30) NOT NULL,status ENUM('pending','approved','rejected') NOT NULL DEFAULT 'pending',reviewed_by INT NULL,reviewed_at DATETIME NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE,FOREIGN KEY(reviewed_by) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS event_staff(event_id BIGINT NOT NULL,user_id INT NOT NULL,assigned_by INT NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(event_id,user_id),FOREIGN KEY(event_id) REFERENCES events(id) ON DELETE CASCADE,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE,FOREIGN KEY(assigned_by) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS bookings(id BIGINT AUTO_INCREMENT PRIMARY KEY,event_id BIGINT NULL,event_title VARCHAR(200) NOT NULL,event_date DATETIME NOT NULL,location VARCHAR(255) NOT NULL,user_email VARCHAR(190) NOT NULL,user_info JSON NOT NULL,tickets JSON NOT NULL,total DECIMAL(10,2) NOT NULL,status VARCHAR(30) NOT NULL,expires_at DATETIME NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS api_tokens(id BIGINT AUTO_INCREMENT PRIMARY KEY,user_id INT NOT NULL,token_hash CHAR(64) NOT NULL UNIQUE,expires_at DATETIME NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS issued_tickets(id CHAR(32) PRIMARY KEY,booking_id BIGINT NOT NULL,event_id BIGINT NOT NULL,token_hash CHAR(64) NOT NULL UNIQUE,qr_cipher TEXT NOT NULL,scanned_at DATETIME NULL,status ENUM('valid','used','cancelled','refunded','expired','transferred') NOT NULL DEFAULT 'valid',ticket_type_id VARCHAR(80) NULL,entry_point VARCHAR(100) NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(booking_id) REFERENCES bookings(id),FOREIGN KEY(event_id) REFERENCES events(id));
CREATE TABLE IF NOT EXISTS plans(id VARCHAR(30) PRIMARY KEY,name VARCHAR(80) NOT NULL,monthly_price INT NOT NULL DEFAULT 0,annual_price INT NOT NULL DEFAULT 0,max_events INT NULL,max_tickets_per_event INT NULL,max_ticket_types INT NULL,max_controllers INT NULL,commission DECIMAL(5,2) NOT NULL DEFAULT 0,features JSON NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS subscriptions(id BIGINT AUTO_INCREMENT PRIMARY KEY,organizer_id INT NOT NULL,plan_id VARCHAR(30) NOT NULL,billing_period ENUM('monthly','annual') NOT NULL,status ENUM('pending_payment','active','grace','expired','cancelled','suspended') NOT NULL DEFAULT 'pending_payment',starts_at DATETIME NULL,ends_at DATETIME NULL,renewal_auto TINYINT(1) NOT NULL DEFAULT 0,adjustment_type ENUM('none','percent','fixed') NOT NULL DEFAULT 'none',adjustment_value DECIMAL(10,2) NOT NULL DEFAULT 0,adjustment_reason VARCHAR(255) NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,INDEX(organizer_id,status),FOREIGN KEY(organizer_id) REFERENCES users(id),FOREIGN KEY(plan_id) REFERENCES plans(id));
CREATE TABLE IF NOT EXISTS subscription_payments(id BIGINT AUTO_INCREMENT PRIMARY KEY,subscription_id BIGINT NOT NULL,amount INT NOT NULL,currency CHAR(3) NOT NULL DEFAULT 'XAF',provider VARCHAR(50) NOT NULL DEFAULT 'unconfigured',provider_reference VARCHAR(190) NULL,status ENUM('pending','paid','failed','refunded') NOT NULL DEFAULT 'pending',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX(provider_reference),FOREIGN KEY(subscription_id) REFERENCES subscriptions(id));
CREATE TABLE IF NOT EXISTS payment_events(id BIGINT AUTO_INCREMENT PRIMARY KEY,provider VARCHAR(50) NOT NULL,provider_event_id VARCHAR(190) NOT NULL,payload JSON NULL,processed_at DATETIME NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,UNIQUE KEY(provider,provider_event_id));
CREATE TABLE IF NOT EXISTS invoices(id BIGINT AUTO_INCREMENT PRIMARY KEY,subscription_id BIGINT NOT NULL,invoice_number VARCHAR(50) NOT NULL UNIQUE,amount INT NOT NULL,currency CHAR(3) NOT NULL DEFAULT 'XAF',status VARCHAR(30) NOT NULL DEFAULT 'issued',pdf_path VARCHAR(255) NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(subscription_id) REFERENCES subscriptions(id));
CREATE TABLE IF NOT EXISTS messages(id BIGINT AUTO_INCREMENT PRIMARY KEY,sender_id INT NOT NULL,recipient_id INT NOT NULL,related_event_id BIGINT NULL,body TEXT NOT NULL,read_at DATETIME NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX(sender_id,recipient_id,created_at),INDEX(recipient_id,read_at),FOREIGN KEY(sender_id) REFERENCES users(id) ON DELETE CASCADE,FOREIGN KEY(recipient_id) REFERENCES users(id) ON DELETE CASCADE,FOREIGN KEY(related_event_id) REFERENCES events(id) ON DELETE SET NULL);
CREATE TABLE IF NOT EXISTS audit_log(id BIGINT AUTO_INCREMENT PRIMARY KEY,actor_email VARCHAR(190) NOT NULL,action VARCHAR(80) NOT NULL,entity_type VARCHAR(80) NOT NULL,entity_id VARCHAR(100) NOT NULL,details JSON NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX(created_at));
CREATE TABLE IF NOT EXISTS api_rate_limits(bucket_key CHAR(64) PRIMARY KEY,hits INT NOT NULL,window_started DATETIME NOT NULL);
